flow.typescript:
// D33 · Part 1~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_flow.ts   (합성 목소리 · 합성 방 울림 · 합성 잡음으로 마이크·스피커 없이 실행)
//   마이크 신호 = 에코 + 사용자 목소리 + 차 소리 → ① 지연 찾기 → ② 에코 제거(NLMS + Geigel) → ③ 잡음 억제(위너) → ④ 자동 음량(AGC)
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

function makeNoise(kind: string, n: number, seed: number = 0): Float32Array {
  // 잡음 세 가지(실효값 1로 맞춤): white = 선풍기처럼 고른 소리 · car = 낮은 소리에 몰린 웅웅 · hum = 120 · 240 Hz 웅 소리 + 약한 잡음
  const g = gauss(seed);
  const x = new Float64Array(n);
  if (kind === "white") for (let i = 0; i < n; i++) x[i] = g();
  else if (kind === "car") {
    const a = 1 - Math.exp((-2 * Math.PI * 300) / SR); // 300 Hz 아래만 통과시키는 1차 필터 두 번
    let integ = 0;
    let l1 = 0;
    let l2 = 0;
    for (let i = 0; i < n; i++) {
      integ = g() + 0.995 * integ; // 낮은 소리가 크게 쌓이는 웅웅
      l1 += a * (integ - l1);
      l2 += a * (l1 - l2);
      x[i] = l2;
    }
  } else for (let i = 0; i < n; i++) x[i] = 0.6 * Math.sin((2 * Math.PI * 120 * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 240 * i) / SR) + 0.3 * g();
  const rms = Math.sqrt(x.reduce((a, v) => a + v * v, 0) / n);
  return Float32Array.from(x, (v) => v / rms);
}

function activeMask(clean: Float32Array): boolean[] {
  const peak = clean.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  return Array.from(clean, (v) => Math.abs(v) > 0.1 * peak);
}

function meanSq(x: ArrayLike<number>, mask: boolean[]): number {
  let s = 0;
  let c = 0;
  for (let i = 0; i < mask.length; i++)
    if (mask[i]) {
      s += x[i] * x[i];
      c++;
    }
  return s / c;
}

function mixSnr(clean: Float32Array, noise: Float32Array, snrDb: number): Float32Array {
  // 말소리가 있는 곳의 에너지 기준으로 잡음 크기를 맞춰 섞는다: SNR = 10 log10(말소리 에너지 / 잡음 에너지)
  const m = activeMask(clean);
  const g = Math.sqrt(meanSq(clean, m) / (meanSq(noise, m) * 10 ** (snrDb / 10)));
  return clean.map((v, i) => v + g * noise[i]);
}

function measuredSnr(clean: Float32Array, noisy: Float32Array): number {
  const m = activeMask(clean);
  return 10 * Math.log10(meanSq(clean, m) / meanSq(noisy.map((v, i) => v - clean[i]), m));
}

function siSdr(y: ArrayLike<number>, ref: ArrayLike<number>): number {
  // 소리 품질 점수(dB): 깨끗한 소리 성분 대 나머지(잡음 · 왜곡). 크기가 달라도 같은 점수(scale-invariant). 높을수록 좋음
  let yr = 0;
  let rr = 0;
  for (let i = 0; i < ref.length; i++) {
    yr += y[i] * ref[i];
    rr += ref[i] * ref[i];
  }
  const alpha = yr / rr;
  let t = 0;
  let r = 0;
  for (let i = 0; i < ref.length; i++) {
    t += (alpha * ref[i]) ** 2;
    r += (y[i] - alpha * ref[i]) ** 2;
  }
  return 10 * Math.log10(t / (r + 1e-15));
}

const CLEAN = place(synthVoice(4.0, 150, 3).map((v) => 0.5 * v), 5.0, 0.6); // 앞 0.6초는 조용함(잡음만) → 잡음 크기를 배울 구간

const NFFT = 512;
const HOP = 128;

function wienerNs(y: Float32Array, noiseSec: number = 0.4, floor: number = 0.1): [Float32Array, Float64Array[]] {
  // 위너 필터 잡음 억제: 주파수마다 '말소리일 몫'만큼만 남긴다. 이득 G = max(1 - 잡음 에너지 / 칸 에너지, floor)
  const win = Float64Array.from({ length: NFFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / NFFT));
  const nFrames = Math.ceil((y.length + NFFT - HOP) / HOP) + 1;
  const spec: [Float64Array, Float64Array][] = [];
  const power: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const start = k * HOP - (NFFT - HOP);
    const re = new Float64Array(NFFT);
    const im = new Float64Array(NFFT);
    for (let i = 0; i < NFFT; i++) re[i] = start + i >= 0 && start + i < y.length ? y[start + i] * win[i] : 0;
    fft(re, im);
    spec.push([re, im]);
    power.push(re.map((v, i) => v * v + im[i] * im[i]));
  }
  const noiseFrames = power.filter((_, k) => (k * HOP - (NFFT - HOP) + NFFT / 2) / SR < noiseSec);
  const N = new Float64Array(NFFT).map((_, f) => noiseFrames.reduce((a, p) => a + p[f], 0) / noiseFrames.length); // 주파수마다 잡음 에너지 = 앞부분(잡음만) 평균
  const out = new Float64Array(y.length);
  const norm = new Float64Array(y.length);
  const gains: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const G = power[k].map((p, f) => Math.max(1 - N[f] / (p + 1e-12), floor)); // 칸마다 이득, floor보다 작아지지 않게
    gains.push(G.slice(0, NFFT / 2 + 1));
    const re = spec[k][0].map((v, f) => v * G[f]);
    const im = spec[k][1].map((v, f) => v * G[f]);
    fft(re, im, true); // 칸 → 다시 소리
    const start = k * HOP - (NFFT - HOP);
    for (let i = 0; i < NFFT; i++)
      if (start + i >= 0 && start + i < y.length) {
        out[start + i] += re[i] * win[i];
        norm[start + i] += win[i] * win[i];
      }
  }
  return [Float32Array.from(out, (v, i) => v / Math.max(norm[i], 1e-8)), gains];
}

const TARGET_DB = -24; // AGC: 목표 크기
const MAX_GAIN_DB = 24; // 최대 이득
const GATE_DB = -42; // 이보다 작으면 말소리가 아니라고 봄

function agcFrame(f: Float32Array, gDb: number, attack: number = 0.3, release: number = 0.05): [Float32Array, number] {
  // 20 ms 조각 하나 + 지금 이득 → 처리된 조각 + 새 이득
  const lv = levelDb(f);
  if (lv > GATE_DB) {
    // 말소리일 때만 목표를 다시 정함
    const want = Math.max(-MAX_GAIN_DB, Math.min(MAX_GAIN_DB, TARGET_DB - lv)); // 원하는 이득 = 목표 크기 − 지금 크기
    gDb += (want < gDb ? attack : release) * (want - gDb); // 줄일 때는 빠르게, 키울 때는 천천히
  }
  const g = 10 ** (gDb / 20);
  return [f.map((v) => Math.max(-1, Math.min(1, v * g))), gDb];
}

function agc(x: Float32Array): Float32Array {
  const out = new Float32Array(x.length);
  let g = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const [y, ng] = agcFrame(x.subarray(i, i + FRAME), g);
    out.set(y, i);
    g = ng;
  }
  return out;
}

function speechLevel(x: Float32Array, ref: Float32Array, start: number = 0): number {
  // ref에서 말소리가 있는 조각들만 골라 x의 크기 재기 (start초 뒤부터)
  const th = levelDb(ref) - 10;
  let s = 0;
  let c = 0;
  for (let i = Math.floor(start * SR); i + FRAME <= ref.length; i += FRAME)
    if (levelDb(ref, i, i + FRAME) > th) {
      for (let j = i; j < i + FRAME; j++) s += x[j] * x[j];
      c += FRAME;
    }
  return 20 * Math.log10(Math.sqrt(s / c) + 1e-9);
}

// 장면 만들기: 비서 에코 + 3.2초 끼어드는 사용자 + 아주 작은 차 소리(-66 dBFS 쯤)
const car = makeNoise("car", MIC_B.length, 1);
const MIC = MIC_B.map((v, i) => v + 10 ** (-66 / 20) * car[i]);
const [u0, u1] = [Math.floor(BARGE_AT * SR), Math.floor(BARGE_AT * SR) + BARGE_LEN];
const [e0, e1] = [Math.floor(2.0 * SR), u0]; // 비서만 말하는 구간

// ① 에코 지연 찾기 (상호상관)
const lag = estimateLag(MIC, FAR);
const absH = Array.from(RIR_ECHO, Math.abs);
const trueLag = Math.floor(DEVICE_DELAY * SR) + absH.indexOf(Math.max(...absH));
console.log(`① 에코 지연 ${lag}샘플 = ${((lag / SR) * 1000).toFixed(1)} ms (정답 ${trueLag})`);
check(Math.abs(lag - trueLag) <= 3, "상호상관의 가장 큰 봉우리가 에코 지연이에요.");
const REF = delayed(FAR, lag - 32);

// ② 에코 제거: 사용자도 말하는 동안(Geigel)에는 배우기를 멈춘다
const DT = geigel(MIC, REF);
const [aec] = nlmsAec(MIC, REF, TAPS, MU, 1e-2, DT);
const erle = erleDb(MIC.subarray(e0, e1), aec.subarray(e0, e1));
console.log(`② 에코 제거: 비서만 말하는 구간 ${levelDb(MIC, e0, e1).toFixed(1)} → ${levelDb(aec, e0, e1).toFixed(1)} dBFS (ERLE ${erle.toFixed(1)} dB)`);
check(erle > 15, "에코를 15 dB 넘게 줄여야 해요.");

// ③ 잡음 억제: 앞 0.4초(비서도 사용자도 조용)에서 잡음을 배운다
const [ns] = wienerNs(aec);
const siRaw = siSdr(MIC.subarray(u0, u1), NEAR.subarray(u0, u1));
const siNs = siSdr(ns.subarray(u0, u1), NEAR.subarray(u0, u1));
console.log(`③ 잡음 억제: 사용자 구간 SI-SDR 처리 전 ${siRaw.toFixed(1)} → 체인(에코 제거 + 잡음 억제) 뒤 ${siNs.toFixed(1)} dB (깨끗한 사용자 목소리 NEAR 기준)`);
check(siNs > siRaw - 0.5 && levelDb(ns, e0, e1) < levelDb(MIC, e0, e1) - 15, "사용자 목소리는 망가뜨리지 않고, 비서 에코·잡음만 줄여야 해요.");

// ④ 자동 음량: 사용자 목소리가 목표 크기 근처로
const out = agc(ns);
const lvIn = speechLevel(MIC, NEAR);
const lvOut = speechLevel(out, NEAR);
console.log(`④ 자동 음량: 사용자 말소리 ${lvIn.toFixed(1)} → ${lvOut.toFixed(1)} dBFS (목표 ${TARGET_DB}) · 에코 구간 남은 소리 ${levelDb(out, e0, e1).toFixed(1)} dBFS`);
check(Math.abs(lvOut - TARGET_DB) < 5, "AGC가 사용자 말소리를 목표 크기 근처로 맞춰야 해요.");

// 체인 끝: VAD가 가짜 끼어들기 없이 진짜 끼어들기만 본다 (필터가 자리 잡은 1.5초 뒤)
const rawStarts = vadStarts(MIC).filter((v) => v > 1.5);
const finalStarts = vadStarts(out).filter((v) => v > 1.5);
console.log(`VAD '말 시작'(1.5초 뒤): 처리 전 ${JSON.stringify(rawStarts)} → 체인 뒤 ${JSON.stringify(finalStarts)} (진짜 ${BARGE_AT}초)`);
check(finalStarts.length === 1 && Math.abs(finalStarts[0] - BARGE_AT) < 0.1, "체인 뒤에는 진짜 끼어들기만 잡혀야 해요.");

path.typescript:
// D33 · Part 1 · 에코 경로: 스피커 → 방 → 마이크 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_path.ts   (합성 목소리 · 합성 방 울림으로 마이크·스피커 없이 실행)
//   스피커 → 방 → 마이크: 비서 소리가 장치 지연 + 방 울림을 거쳐 작게 돌아오고, 이 에코를 VAD가 '사용자 말'로 착각하는지 확인
const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

// 1) 에코 경로: 첫 봉우리 = 직접 경로, 뒤따르는 작은 봉우리들 = 벽 반사 (대체 경로: pyroomacoustics 대신 합성 방 울림)
const absH = Array.from(RIR_ECHO, Math.abs);
const direct = absH.indexOf(Math.max(...absH));
const tailDb = 20 * Math.log10(Math.max(...absH.slice(direct + 1)) / absH[direct]);
const meanAbs = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;
console.log(`방 울림 ${RIR_ECHO.length}샘플(${((RIR_ECHO.length / SR) * 1000).toFixed(0)} ms) · 직접 소리 ${direct}샘플째 · 반사 꼬리는 직접 소리보다 ${tailDb.toFixed(1)} dB 작음`);
check(direct === 12 && tailDb < -6 && meanAbs(absH.slice(13, 140)) > 3 * meanAbs(absH.slice(340)), "직접 소리가 가장 크고 반사는 점점 작아져요.");

// 2) 에코가 얼마나 작게 돌아오나: 에코 경로 손실 ERL = 스피커로 나간 소리 크기 − 마이크에 들어온 에코 크기
const [a, b] = [Math.floor(1.0 * SR), Math.floor(BOT_END * SR)];
const erl = levelDb(FAR, a, b) - levelDb(ECHO, a, b);
console.log(`스피커 소리 ${levelDb(FAR, a, b).toFixed(1)} dBFS → 마이크의 에코 ${levelDb(ECHO, a, b).toFixed(1)} dBFS (ERL ${erl.toFixed(1)} dB)`);
const trueDelay = Math.floor(DEVICE_DELAY * SR) + direct;
console.log(`에코는 스피커 소리보다 장치 지연 ${DEVICE_DELAY * 1000} ms + 직접 경로 ${direct}샘플 = ${trueDelay}샘플(${((trueDelay / SR) * 1000).toFixed(1)} ms) 늦게 도착`);
check(erl > 10 && erl < 30, "에코는 원래 소리보다 10 ~ 30 dB 작게 돌아와요.");
const peakEcho = ECHO.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
const first = ECHO.findIndex((v) => Math.abs(v) > 0.02 * peakEcho);
check(first - Math.floor(0.5 * SR) >= trueDelay - 400, "에코는 비서 소리가 나가기 시작한 뒤 지연만큼 늦게 시작해요.");

// 3) 가짜 끼어들기: 같은 VAD가 에코를 사용자 말로 착각하는가
const vA = vadStarts(MIC_A);
const vB = vadStarts(MIC_B);
console.log(`장면 A (에코만, 사용자 조용): VAD '말 시작' ${JSON.stringify(vA)}   장면 B (${BARGE_AT}초 끼어들기): ${JSON.stringify(vB)}`);
for (const th of [-38, -32, -26]) console.log(`  문턱 ${th} dBFS → 장면 A ${JSON.stringify(vadStarts(MIC_A, th))} · 장면 B ${JSON.stringify(vadStarts(MIC_B, th))}`);
check(vA.length >= 1 && vA[0] < 1.0, "사용자가 조용한데도 비서 에코에서 '말 시작'이 잡혀요(가짜 끼어들기).");
const v26 = vadStarts(MIC_A, -26);
check(v26.length === 0 || v26[0] > 1.0, "문턱을 높이면 가짜는 줄지만, 작게 끼어드는 진짜 말도 놓쳐요 → 에코 제거가 필요해요.");

xcorr.typescript:
// D33 · Part 1 · 상호상관으로 에코 지연 찾기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_xcorr.ts   (합성 목소리 · 합성 방 울림으로 마이크·스피커 없이 실행)
//   상호상관으로 에코 지연 찾기: 스피커 기준 신호를 한 칸씩 밀어 마이크와 가장 닮은 칸 = 에코가 늦은 샘플 수
const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

function corrAt(mic: Float32Array, ref: Float32Array, lag: number): number {
  let s = 0;
  for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
  return s;
}

function corrCoef(a: Float32Array, b: Float32Array): number {
  const m = (x: Float32Array): number => x.reduce((s, v) => s + v, 0) / x.length;
  const ma = m(a);
  const mb = m(b);
  let ab = 0;
  let aa = 0;
  let bb = 0;
  for (let i = 0; i < a.length; i++) {
    ab += (a[i] - ma) * (b[i] - mb);
    aa += (a[i] - ma) ** 2;
    bb += (b[i] - mb) ** 2;
  }
  return ab / Math.sqrt(aa * bb);
}

const lag = estimateLag(MIC_A, FAR); // 가장 큰 값의 '위치' (0 ~ 2000샘플만 훑음)
const absH = Array.from(RIR_ECHO, Math.abs);
const trueLag = Math.floor(DEVICE_DELAY * SR) + absH.indexOf(Math.max(...absH)); // 정답 = 장치 지연 + 직접 경로 도착
console.log(`찾은 지연: ${lag}샘플 = ${((lag / SR) * 1000).toFixed(1)} ms  (정답 ${trueLag}샘플 = ${((trueLag / SR) * 1000).toFixed(1)} ms)`);
check(Math.abs(lag - trueLag) <= 3, "가장 큰 상관 값의 위치(인덱스)가 에코 지연이에요.");

// 봉우리 모양: 첫 봉우리가 가장 크고, 뒤의 작은 봉우리들은 벽 반사
const peak = Math.abs(corrAt(MIC_A, FAR, lag));
const later = Math.abs(corrAt(MIC_A, FAR, lag + 60)) / peak;
console.log(`봉우리 세기: 정점 1.00 · 정점에서 60샘플 뒤 ${later.toFixed(2)} (벽 반사로 작아짐)`);
check(later < 0.5, "정점이 가장 크고 반사 봉우리는 작아야 해요.");

// 지연을 알면: 기준 신호를 그만큼 늦춘 REF를 만들 수 있다 (NLMS에는 32샘플 일찍 맞춰 넣어 앞쪽 경로도 배우게 함)
const before = Math.abs(corrCoef(MIC_A, FAR));
const after = Math.abs(corrCoef(MIC_A, delayed(FAR, lag)));
console.log(`마이크와 기준 신호의 닮은 정도: 지연 맞추기 전 ${before.toFixed(2)} → 맞춘 뒤 ${after.toFixed(2)}`);
check(after > 3 * before && after > 0.5, "지연을 맞추면 마이크와 기준 신호가 훨씬 닮아요.");

// 기준 신호가 사라진 장면(사용자만 말함)에서는 뚜렷한 봉우리가 없다 → 지연을 믿을 수 없음
const onlyUser = NEAR.map((v, i) => v + FLOOR[i]);
const ratio = Math.abs(corrAt(onlyUser, FAR, estimateLag(onlyUser, FAR))) / peak;
console.log(`사용자 목소리만 있는 마이크와의 최대 상관: 에코 장면의 ${ratio.toFixed(2)}배`);
check(ratio < 0.5, "에코가 없으면 상관 봉우리도 작아요.");

nlms.typescript:
// D33 · Part 2 · NLMS 에코 제거기와 ERLE — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_nlms.ts   (합성 목소리 · 합성 방 울림으로 마이크·스피커 없이 실행 · 약 10초)
//   NLMS 적응 필터가 에코 경로를 배우며 에코를 지운다: ERLE(몇 dB 줄였나) · 기억 길이(taps) · 걸음 크기(μ)
const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

const lag = estimateLag(MIC_A, FAR);
const REF = delayed(FAR, lag - 32); // 지연만큼 늦춘 기준 신호 (32샘플 여유)

const [e, w] = nlmsAec(MIC_A, REF);
const seg = (x: Float32Array): Float32Array => slice(x, 2.0, BOT_END); // 처음 1.5초는 배우는 중이라 빼고 잼
const erle = erleDb(seg(MIC_A), seg(e));
console.log(`마이크 에코 ${levelDb(seg(MIC_A)).toFixed(1)} dBFS → NLMS 뒤 ${levelDb(seg(e)).toFixed(1)} dBFS · ERLE ${erle.toFixed(1)} dB (일반적인 목표 15 ~ 25 dB 이상)`);
check(erle > 25, "에코를 충분히 지워야 해요(ERLE 25 dB 이상).");

// 배운 w는 진짜 에코 경로와 닮았는가: 진짜 경로 = 32샘플 여유 + 장치 지연 + 방 울림 × 결합
const trueW = new Float64Array(TAPS);
const shift = Math.floor(DEVICE_DELAY * SR) - (lag - 32); // REF가 기준 신호보다 (lag - 32)샘플 늦으니 그만큼 뺌
for (let k = 0; k < Math.min(RIR_ECHO.length, TAPS - shift); k++) trueW[shift + k] = RIR_ECHO[k] * COUPLING;
const dot = (a: Float64Array, b: Float64Array): number => a.reduce((s, v, i) => s + v * b[i], 0);
const wCorr = dot(w, trueW) / Math.sqrt(dot(w, w) * dot(trueW, trueW));
console.log(`배운 필터 w와 진짜 에코 경로의 닮은 정도 ${wCorr.toFixed(3)}`);
check(wCorr > 0.95, "충분히 배우면 w가 진짜 에코 경로를 닮아요.");

// 손잡이 taps · μ 비교: 짧으면 방 울림 꼬리를 못 담고, μ가 작으면 느리고, 너무 크면 마지막에 흔들린다
const rows: Record<string, [number, number]> = {};
for (const [taps, mu] of [[256, 0.5], [512, 0.1], [512, 0.5], [512, 1.0]]) {
  const [out] = nlmsAec(MIC_A, REF, taps, mu);
  const first = erleDb(slice(MIC_A, 0.5, 1.5), slice(out, 0.5, 1.5));
  const late = erleDb(seg(MIC_A), seg(out));
  rows[`${taps},${mu}`] = [first, late];
  console.log(`taps=${String(taps).padEnd(4)} μ=${String(mu).padEnd(4)} 첫 1초 ERLE ${first.toFixed(1).padStart(6)} dB · 2초 뒤 ERLE ${late.toFixed(1).padStart(6)} dB`);
}
check(rows["512,0.5"][0] > rows["512,0.1"][0], "μ가 크면 처음에 더 빨리 배워요.");
check(rows["512,0.5"][1] > rows["256,0.5"][1] + 5, "기억이 방 울림보다 짧으면(taps 256) 꼬리 에코가 남아 ERLE이 낮아요.");

// 실시간으로 쓸 수 있나: 샘플마다 taps번 곱셈
console.log(`샘플마다 곱셈 약 ${2 * TAPS}번 → 소리 1초에 ${(2 * TAPS * SR / 1e6).toFixed(0)}백만 번 (CPU로 충분)`);

dt.typescript:
// D33 · Part 2 · 더블토크와 Geigel — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_dt.ts   (합성 목소리 · 합성 방 울림으로 마이크·스피커 없이 실행 · 약 10초)
//   더블토크: 비서 에코와 사용자 목소리가 겹칠 때 계속 배우면 사용자 목소리까지 망가짐 → Geigel이 감지하면 배우기를 멈춤
const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

const lag = estimateLag(MIC_A, FAR);
const REF = delayed(FAR, lag - 32);

const DT = geigel(MIC_B, REF); // true = 사용자도 말하는 중
const [u0, u1] = [Math.floor(BARGE_AT * SR), Math.floor(BARGE_AT * SR) + BARGE_LEN];
const [E_keep] = nlmsAec(MIC_B, REF); // 멈추지 않음
const [E_stop] = nlmsAec(MIC_B, REF, TAPS, MU, 1e-2, DT); // Geigel로 멈춤

const frac = (a: number, b: number): number => DT.slice(a, b).filter(Boolean).length / (b - a);
const hit = frac(u0, u1);
const falseAlarm = frac(Math.floor(1.0 * SR), u0);
console.log(`Geigel이 '사용자도 말하는 중'으로 본 비율: 끼어들기 동안 ${(hit * 100).toFixed(0)}% · 비서만 말할 때 ${(falseAlarm * 100).toFixed(0)}%`);
check(hit > 0.4 && falseAlarm < 0.05, "끼어들기 때는 자주, 비서만 말할 때는 거의 안 켜져야 해요.");

const rows: [string, number, number][] = [];
for (const [name, out] of [["처리 전", MIC_B], ["NLMS (계속 배움)", E_keep], ["NLMS + Geigel", E_stop]] as [string, Float32Array][]) {
  const echoLeft = levelDb(out, Math.floor(2.0 * SR), u0); // 끼어들기 전 남은 에코
  const diff = out.slice(u0, u1).map((v, i) => v - NEAR[u0 + i]);
  const damage = levelDb(diff) - levelDb(NEAR, u0, u1); // 사용자 목소리가 얼마나 망가졌나 (낮을수록 좋음)
  rows.push([name, echoLeft, damage]);
  console.log(`${name.padEnd(18)} 끼어들기 전 남은 에코 ${echoLeft.toFixed(1).padStart(7)} dBFS · 사용자 목소리 망가짐 ${damage.toFixed(1).padStart(6)} dB`);
}
check(rows[2][2] < rows[1][2] - 15, "배우기를 멈추면 사용자 목소리 왜곡이 훨씬 작아요.");
check(rows[2][2] < -15 && rows[1][2] > -5, "계속 배우면 사용자 목소리와 같은 크기의 왜곡이 생겨요.");

// 에코 제거 뒤에는 VAD가 가짜 끼어들기를 하지 않고, 진짜 끼어들기만 잡는다
const vsRaw = vadStarts(MIC_B);
const vsStop = vadStarts(E_stop);
const settled = vsStop.filter((v) => v > 1.5); // 처음 1초 남짓은 필터가 배우는 중이라 에코가 조금 남아 있음
console.log(`VAD '말 시작': 처리 전 ${JSON.stringify(vsRaw)} → Geigel + NLMS 뒤 ${JSON.stringify(vsStop)} (진짜 끼어들기 ${BARGE_AT}초) · 1.5초 뒤만 보면 ${JSON.stringify(settled)}`);
check(settled.length === 1 && Math.abs(settled[0] - BARGE_AT) < 0.1, "필터가 자리 잡은 뒤에는 진짜 끼어들기 한 번만 잡혀요.");

snr.typescript:
// D33 · Part 3 · 잡음 만들기와 SNR 맞추기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_snr.ts   (합성 목소리 · 합성 잡음으로 실행)
//   잡음 세 가지(white · car · hum)를 만들어 원하는 SNR로 섞고, 정말 그 SNR이 되는지 · 소리 품질 점수(SI-SDR)가 어떻게 움직이는지 확인
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

function makeNoise(kind: string, n: number, seed: number = 0): Float32Array {
  // 잡음 세 가지(실효값 1로 맞춤): white = 선풍기처럼 고른 소리 · car = 낮은 소리에 몰린 웅웅 · hum = 120 · 240 Hz 웅 소리 + 약한 잡음
  const g = gauss(seed);
  const x = new Float64Array(n);
  if (kind === "white") for (let i = 0; i < n; i++) x[i] = g();
  else if (kind === "car") {
    const a = 1 - Math.exp((-2 * Math.PI * 300) / SR); // 300 Hz 아래만 통과시키는 1차 필터 두 번
    let integ = 0;
    let l1 = 0;
    let l2 = 0;
    for (let i = 0; i < n; i++) {
      integ = g() + 0.995 * integ; // 낮은 소리가 크게 쌓이는 웅웅
      l1 += a * (integ - l1);
      l2 += a * (l1 - l2);
      x[i] = l2;
    }
  } else for (let i = 0; i < n; i++) x[i] = 0.6 * Math.sin((2 * Math.PI * 120 * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 240 * i) / SR) + 0.3 * g();
  const rms = Math.sqrt(x.reduce((a, v) => a + v * v, 0) / n);
  return Float32Array.from(x, (v) => v / rms);
}

function activeMask(clean: Float32Array): boolean[] {
  const peak = clean.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  return Array.from(clean, (v) => Math.abs(v) > 0.1 * peak);
}

function meanSq(x: ArrayLike<number>, mask: boolean[]): number {
  let s = 0;
  let c = 0;
  for (let i = 0; i < mask.length; i++)
    if (mask[i]) {
      s += x[i] * x[i];
      c++;
    }
  return s / c;
}

function mixSnr(clean: Float32Array, noise: Float32Array, snrDb: number): Float32Array {
  // 말소리가 있는 곳의 에너지 기준으로 잡음 크기를 맞춰 섞는다: SNR = 10 log10(말소리 에너지 / 잡음 에너지)
  const m = activeMask(clean);
  const g = Math.sqrt(meanSq(clean, m) / (meanSq(noise, m) * 10 ** (snrDb / 10)));
  return clean.map((v, i) => v + g * noise[i]);
}

function measuredSnr(clean: Float32Array, noisy: Float32Array): number {
  const m = activeMask(clean);
  return 10 * Math.log10(meanSq(clean, m) / meanSq(noisy.map((v, i) => v - clean[i]), m));
}

function siSdr(y: ArrayLike<number>, ref: ArrayLike<number>): number {
  // 소리 품질 점수(dB): 깨끗한 소리 성분 대 나머지(잡음 · 왜곡). 크기가 달라도 같은 점수(scale-invariant). 높을수록 좋음
  let yr = 0;
  let rr = 0;
  for (let i = 0; i < ref.length; i++) {
    yr += y[i] * ref[i];
    rr += ref[i] * ref[i];
  }
  const alpha = yr / rr;
  let t = 0;
  let r = 0;
  for (let i = 0; i < ref.length; i++) {
    t += (alpha * ref[i]) ** 2;
    r += (y[i] - alpha * ref[i]) ** 2;
  }
  return 10 * Math.log10(t / (r + 1e-15));
}

const CLEAN = place(synthVoice(4.0, 150, 3).map((v) => 0.5 * v), 5.0, 0.6); // 앞 0.6초는 조용함(잡음만) → 잡음 크기를 배울 구간

const NFFT = 512;
const HOP = 128;

function wienerNs(y: Float32Array, noiseSec: number = 0.4, floor: number = 0.1): [Float32Array, Float64Array[]] {
  // 위너 필터 잡음 억제: 주파수마다 '말소리일 몫'만큼만 남긴다. 이득 G = max(1 - 잡음 에너지 / 칸 에너지, floor)
  const win = Float64Array.from({ length: NFFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / NFFT));
  const nFrames = Math.ceil((y.length + NFFT - HOP) / HOP) + 1;
  const spec: [Float64Array, Float64Array][] = [];
  const power: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const start = k * HOP - (NFFT - HOP);
    const re = new Float64Array(NFFT);
    const im = new Float64Array(NFFT);
    for (let i = 0; i < NFFT; i++) re[i] = start + i >= 0 && start + i < y.length ? y[start + i] * win[i] : 0;
    fft(re, im);
    spec.push([re, im]);
    power.push(re.map((v, i) => v * v + im[i] * im[i]));
  }
  const noiseFrames = power.filter((_, k) => (k * HOP - (NFFT - HOP) + NFFT / 2) / SR < noiseSec);
  const N = new Float64Array(NFFT).map((_, f) => noiseFrames.reduce((a, p) => a + p[f], 0) / noiseFrames.length); // 주파수마다 잡음 에너지 = 앞부분(잡음만) 평균
  const out = new Float64Array(y.length);
  const norm = new Float64Array(y.length);
  const gains: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const G = power[k].map((p, f) => Math.max(1 - N[f] / (p + 1e-12), floor)); // 칸마다 이득, floor보다 작아지지 않게
    gains.push(G.slice(0, NFFT / 2 + 1));
    const re = spec[k][0].map((v, f) => v * G[f]);
    const im = spec[k][1].map((v, f) => v * G[f]);
    fft(re, im, true); // 칸 → 다시 소리
    const start = k * HOP - (NFFT - HOP);
    for (let i = 0; i < NFFT; i++)
      if (start + i >= 0 && start + i < y.length) {
        out[start + i] += re[i] * win[i];
        norm[start + i] += win[i] * win[i];
      }
  }
  return [Float32Array.from(out, (v, i) => v / Math.max(norm[i], 1e-8)), gains];
}

const TARGET_DB = -24; // AGC: 목표 크기
const MAX_GAIN_DB = 24; // 최대 이득
const GATE_DB = -42; // 이보다 작으면 말소리가 아니라고 봄

function agcFrame(f: Float32Array, gDb: number, attack: number = 0.3, release: number = 0.05): [Float32Array, number] {
  // 20 ms 조각 하나 + 지금 이득 → 처리된 조각 + 새 이득
  const lv = levelDb(f);
  if (lv > GATE_DB) {
    // 말소리일 때만 목표를 다시 정함
    const want = Math.max(-MAX_GAIN_DB, Math.min(MAX_GAIN_DB, TARGET_DB - lv)); // 원하는 이득 = 목표 크기 − 지금 크기
    gDb += (want < gDb ? attack : release) * (want - gDb); // 줄일 때는 빠르게, 키울 때는 천천히
  }
  const g = 10 ** (gDb / 20);
  return [f.map((v) => Math.max(-1, Math.min(1, v * g))), gDb];
}

function agc(x: Float32Array): Float32Array {
  const out = new Float32Array(x.length);
  let g = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const [y, ng] = agcFrame(x.subarray(i, i + FRAME), g);
    out.set(y, i);
    g = ng;
  }
  return out;
}

function speechLevel(x: Float32Array, ref: Float32Array, start: number = 0): number {
  // ref에서 말소리가 있는 조각들만 골라 x의 크기 재기 (start초 뒤부터)
  const th = levelDb(ref) - 10;
  let s = 0;
  let c = 0;
  for (let i = Math.floor(start * SR); i + FRAME <= ref.length; i += FRAME)
    if (levelDb(ref, i, i + FRAME) > th) {
      for (let j = i; j < i + FRAME; j++) s += x[j] * x[j];
      c += FRAME;
    }
  return 20 * Math.log10(Math.sqrt(s / c) + 1e-9);
}

const KINDS = ["white", "car", "hum"];
const SNRS = [-5, 0, 5, 10, 20];
const noises: Record<string, Float32Array> = {};
KINDS.forEach((k, i) => (noises[k] = makeNoise(k, CLEAN.length, i)));

// 1) 목표 SNR로 섞으면 실제로 잰 SNR이 목표와 같은가
console.log("목표 SNR → 실제 SNR (dB)");
let worst = 0;
for (const k of KINDS) {
  const got = SNRS.map((s) => measuredSnr(CLEAN, mixSnr(CLEAN, noises[k], s)));
  worst = Math.max(worst, ...got.map((g, i) => Math.abs(g - SNRS[i])));
  console.log(`  ${k.padEnd(6)}`, SNRS.map((s, i) => `${String(s).padStart(3)}→${got[i].toFixed(2).padStart(6)}`).join("  "));
}
check(worst < 0.05, "SNR = 10 log10(말소리 에너지 / 잡음 에너지)에 맞게 잡음 크기를 정해야 해요.");

// 2) 잡음은 색이 달라요: 낮은 소리(300 Hz 아래)에 에너지가 얼마나 몰렸나
function lowShare(x: Float32Array): number {
  const nfft = 131072;
  const p = powerSpectrum(x, nfft);
  const cut = Math.floor((300 * nfft) / SR);
  let low = 0;
  let all = 0;
  p.forEach((v, k) => {
    all += v;
    if (k < cut) low += v;
  });
  return low / all;
}
const shares: Record<string, number> = {};
for (const k of KINDS) shares[k] = lowShare(noises[k]);
console.log("300 Hz 아래 에너지 비율:", Object.fromEntries(KINDS.map((k) => [k, Math.round(shares[k] * 100) / 100])));
check(shares.car > 0.9 && shares.white < 0.1 && shares.hum > 0.5, "차 소리는 낮은 쪽, 선풍기(white)는 고르게, 웅 소리(hum)는 120 · 240 Hz에 몰려요.");

// 3) 소리 품질 점수 SI-SDR: 크기가 달라도 같고, SNR이 높을수록 높다
const noisy0 = mixSnr(CLEAN, noises.white, 0);
const noisy20 = mixSnr(CLEAN, noises.white, 20);
const s0 = siSdr(noisy0, CLEAN);
const s20 = siSdr(noisy20, CLEAN);
const sScaled = siSdr(noisy0.map((v) => 3 * v), CLEAN);
console.log(`SI-SDR: SNR 0 dB → ${s0.toFixed(1)} · SNR 20 dB → ${s20.toFixed(1)} · 0 dB 소리를 3배 키워도 ${sScaled.toFixed(1)} · 깨끗한 소리 그대로 ${siSdr(CLEAN, CLEAN).toFixed(0)}`);
check(Math.abs(sScaled - s0) < 1e-6 && s20 > s0 + 15, "SI-SDR은 소리 크기가 아니라 '깨끗한 성분의 몫'을 재요.");
check(s0 > -8 && s0 < 1 && s20 > 12 && s20 < 20, "SI-SDR은 SNR과 비슷하지만, 잡음이 말 사이 쉬는 구간에도 있어 조금 낮게 나와요.");

wiener.typescript:
// D33 · Part 3 · 위너 필터 잡음 억제 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_wiener.ts   (합성 목소리 · 합성 잡음으로 실행)
//   위너 필터 잡음 억제: 앞 0.4초(잡음만)로 주파수마다 잡음 에너지를 배워, 칸마다 '말소리일 몫'만 남기기 → SI-SDR이 얼마나 오르나
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

function makeNoise(kind: string, n: number, seed: number = 0): Float32Array {
  // 잡음 세 가지(실효값 1로 맞춤): white = 선풍기처럼 고른 소리 · car = 낮은 소리에 몰린 웅웅 · hum = 120 · 240 Hz 웅 소리 + 약한 잡음
  const g = gauss(seed);
  const x = new Float64Array(n);
  if (kind === "white") for (let i = 0; i < n; i++) x[i] = g();
  else if (kind === "car") {
    const a = 1 - Math.exp((-2 * Math.PI * 300) / SR); // 300 Hz 아래만 통과시키는 1차 필터 두 번
    let integ = 0;
    let l1 = 0;
    let l2 = 0;
    for (let i = 0; i < n; i++) {
      integ = g() + 0.995 * integ; // 낮은 소리가 크게 쌓이는 웅웅
      l1 += a * (integ - l1);
      l2 += a * (l1 - l2);
      x[i] = l2;
    }
  } else for (let i = 0; i < n; i++) x[i] = 0.6 * Math.sin((2 * Math.PI * 120 * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 240 * i) / SR) + 0.3 * g();
  const rms = Math.sqrt(x.reduce((a, v) => a + v * v, 0) / n);
  return Float32Array.from(x, (v) => v / rms);
}

function activeMask(clean: Float32Array): boolean[] {
  const peak = clean.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  return Array.from(clean, (v) => Math.abs(v) > 0.1 * peak);
}

function meanSq(x: ArrayLike<number>, mask: boolean[]): number {
  let s = 0;
  let c = 0;
  for (let i = 0; i < mask.length; i++)
    if (mask[i]) {
      s += x[i] * x[i];
      c++;
    }
  return s / c;
}

function mixSnr(clean: Float32Array, noise: Float32Array, snrDb: number): Float32Array {
  // 말소리가 있는 곳의 에너지 기준으로 잡음 크기를 맞춰 섞는다: SNR = 10 log10(말소리 에너지 / 잡음 에너지)
  const m = activeMask(clean);
  const g = Math.sqrt(meanSq(clean, m) / (meanSq(noise, m) * 10 ** (snrDb / 10)));
  return clean.map((v, i) => v + g * noise[i]);
}

function measuredSnr(clean: Float32Array, noisy: Float32Array): number {
  const m = activeMask(clean);
  return 10 * Math.log10(meanSq(clean, m) / meanSq(noisy.map((v, i) => v - clean[i]), m));
}

function siSdr(y: ArrayLike<number>, ref: ArrayLike<number>): number {
  // 소리 품질 점수(dB): 깨끗한 소리 성분 대 나머지(잡음 · 왜곡). 크기가 달라도 같은 점수(scale-invariant). 높을수록 좋음
  let yr = 0;
  let rr = 0;
  for (let i = 0; i < ref.length; i++) {
    yr += y[i] * ref[i];
    rr += ref[i] * ref[i];
  }
  const alpha = yr / rr;
  let t = 0;
  let r = 0;
  for (let i = 0; i < ref.length; i++) {
    t += (alpha * ref[i]) ** 2;
    r += (y[i] - alpha * ref[i]) ** 2;
  }
  return 10 * Math.log10(t / (r + 1e-15));
}

const CLEAN = place(synthVoice(4.0, 150, 3).map((v) => 0.5 * v), 5.0, 0.6); // 앞 0.6초는 조용함(잡음만) → 잡음 크기를 배울 구간

const NFFT = 512;
const HOP = 128;

function wienerNs(y: Float32Array, noiseSec: number = 0.4, floor: number = 0.1): [Float32Array, Float64Array[]] {
  // 위너 필터 잡음 억제: 주파수마다 '말소리일 몫'만큼만 남긴다. 이득 G = max(1 - 잡음 에너지 / 칸 에너지, floor)
  const win = Float64Array.from({ length: NFFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / NFFT));
  const nFrames = Math.ceil((y.length + NFFT - HOP) / HOP) + 1;
  const spec: [Float64Array, Float64Array][] = [];
  const power: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const start = k * HOP - (NFFT - HOP);
    const re = new Float64Array(NFFT);
    const im = new Float64Array(NFFT);
    for (let i = 0; i < NFFT; i++) re[i] = start + i >= 0 && start + i < y.length ? y[start + i] * win[i] : 0;
    fft(re, im);
    spec.push([re, im]);
    power.push(re.map((v, i) => v * v + im[i] * im[i]));
  }
  const noiseFrames = power.filter((_, k) => (k * HOP - (NFFT - HOP) + NFFT / 2) / SR < noiseSec);
  const N = new Float64Array(NFFT).map((_, f) => noiseFrames.reduce((a, p) => a + p[f], 0) / noiseFrames.length); // 주파수마다 잡음 에너지 = 앞부분(잡음만) 평균
  const out = new Float64Array(y.length);
  const norm = new Float64Array(y.length);
  const gains: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const G = power[k].map((p, f) => Math.max(1 - N[f] / (p + 1e-12), floor)); // 칸마다 이득, floor보다 작아지지 않게
    gains.push(G.slice(0, NFFT / 2 + 1));
    const re = spec[k][0].map((v, f) => v * G[f]);
    const im = spec[k][1].map((v, f) => v * G[f]);
    fft(re, im, true); // 칸 → 다시 소리
    const start = k * HOP - (NFFT - HOP);
    for (let i = 0; i < NFFT; i++)
      if (start + i >= 0 && start + i < y.length) {
        out[start + i] += re[i] * win[i];
        norm[start + i] += win[i] * win[i];
      }
  }
  return [Float32Array.from(out, (v, i) => v / Math.max(norm[i], 1e-8)), gains];
}

const TARGET_DB = -24; // AGC: 목표 크기
const MAX_GAIN_DB = 24; // 최대 이득
const GATE_DB = -42; // 이보다 작으면 말소리가 아니라고 봄

function agcFrame(f: Float32Array, gDb: number, attack: number = 0.3, release: number = 0.05): [Float32Array, number] {
  // 20 ms 조각 하나 + 지금 이득 → 처리된 조각 + 새 이득
  const lv = levelDb(f);
  if (lv > GATE_DB) {
    // 말소리일 때만 목표를 다시 정함
    const want = Math.max(-MAX_GAIN_DB, Math.min(MAX_GAIN_DB, TARGET_DB - lv)); // 원하는 이득 = 목표 크기 − 지금 크기
    gDb += (want < gDb ? attack : release) * (want - gDb); // 줄일 때는 빠르게, 키울 때는 천천히
  }
  const g = 10 ** (gDb / 20);
  return [f.map((v) => Math.max(-1, Math.min(1, v * g))), gDb];
}

function agc(x: Float32Array): Float32Array {
  const out = new Float32Array(x.length);
  let g = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const [y, ng] = agcFrame(x.subarray(i, i + FRAME), g);
    out.set(y, i);
    g = ng;
  }
  return out;
}

function speechLevel(x: Float32Array, ref: Float32Array, start: number = 0): number {
  // ref에서 말소리가 있는 조각들만 골라 x의 크기 재기 (start초 뒤부터)
  const th = levelDb(ref) - 10;
  let s = 0;
  let c = 0;
  for (let i = Math.floor(start * SR); i + FRAME <= ref.length; i += FRAME)
    if (levelDb(ref, i, i + FRAME) > th) {
      for (let j = i; j < i + FRAME; j++) s += x[j] * x[j];
      c += FRAME;
    }
  return 20 * Math.log10(Math.sqrt(s / c) + 1e-9);
}

const KINDS = ["white", "car", "hum"];
const rows: Record<string, [number, number]> = {};
KINDS.forEach((k, i) => {
  const noisy = mixSnr(CLEAN, makeNoise(k, CLEAN.length, i), 5); // 말소리 대 잡음 5 dB
  const [out] = wienerNs(noisy);
  rows[k] = [siSdr(noisy, CLEAN), siSdr(out, CLEAN)];
  console.log(`${k.padEnd(6)} SI-SDR 잡음 섞임 ${rows[k][0].toFixed(1).padStart(5)} dB → 위너 ${rows[k][1].toFixed(1).padStart(5)} dB (+${(rows[k][1] - rows[k][0]).toFixed(1)})`);
});
check(Object.values(rows).every(([before, after]) => after - before > 3), "위너 필터는 정해진 잡음이면 SI-SDR을 3 dB 넘게 올려요.");

// 이득 G의 모양: 말소리가 있는 칸은 크게 남기고, 잡음뿐인 칸은 floor까지 줄인다
const noisy = mixSnr(CLEAN, makeNoise("car", CLEAN.length, 1), 5);
const [, G] = wienerNs(noisy);
const center = (k: number): number => (k * HOP - (NFFT - HOP) + NFFT / 2) / SR; // k번째 프레임의 가운데 시각(초)
const lowBins = Math.floor((1000 * NFFT) / SR); // 1 kHz 아래 칸 수
const meanG = (from: number, to: number): number => {
  let s = 0;
  let c = 0;
  G.forEach((g, k) => {
    if (center(k) >= from && center(k) < to) for (let f = 0; f < lowBins; f++, c++) s += g[f];
  });
  return s / c;
};
const gNoise = meanG(0, 0.4);
const gSpeech = meanG(1.0, 4.0);
console.log(`1 kHz 아래 평균 이득 G: 잡음만 있는 앞 0.4초 ${gNoise.toFixed(2)} → 말소리 구간 ${gSpeech.toFixed(2)}`);
check(gSpeech > 2 * gNoise, "말소리가 있는 칸의 이득이 잡음뿐인 칸보다 훨씬 커야 해요.");
check(G.every((g) => g.every((v) => v >= 0.1 - 1e-9)), "이득은 floor(0.1)보다 작아지지 않아요.");

// 손잡이 floor: 0이면 잡음이 가장 많이 줄고, 1이면 이득이 늘 1이라 처리 안 한 것과 같다
console.log("floor에 따른 SI-SDR (car, 5 dB):");
const scores: Record<string, number> = {};
for (const fl of [0, 0.1, 0.5, 1]) {
  scores[fl] = siSdr(wienerNs(noisy, 0.4, fl)[0], CLEAN);
  console.log(`  floor ${String(fl).padEnd(4)} → ${scores[fl].toFixed(1).padStart(5)} dB`);
}
check(Math.abs(scores[1] - siSdr(noisy, CLEAN)) < 0.5, "floor 1.0이면 이득이 늘 1이라 처리 안 한 것과 같아요.");
check(Math.max(scores[0], scores[0.1]) > scores[1] + 3, "floor가 작을수록 잡음이 더 줄어요.");

// 앞부분에 잡음만 있는 구간이 없으면 말소리를 잡음으로 배워 효과가 줄어든다
const shiftN = Math.floor(0.8 * SR);
const speechFirst = Float32Array.from(CLEAN, (_, i) => CLEAN[(i + shiftN) % CLEAN.length]); // 말소리가 0초부터 시작하게 돌려놓음
const noisySf = mixSnr(speechFirst, makeNoise("car", speechFirst.length, 1), 5);
const gainSf = siSdr(wienerNs(noisySf)[0], speechFirst) - siSdr(noisySf, speechFirst);
const gainCar = rows.car[1] - rows.car[0];
console.log(`잡음만 있는 구간이 없을 때 SI-SDR 변화 ${gainSf.toFixed(1)} dB (있을 때 ${gainCar.toFixed(1)} dB)`);
check(gainSf < gainCar - 2, "잡음만 있는 구간으로 잡음을 배워야 효과가 커요(VAD가 필요한 이유).");

agc.typescript:
// D33 · Part 4 · 자동 음량(AGC) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_agc.ts   (합성 목소리로 실행)
//   자동 음량(AGC): 20 ms 조각마다 목표 크기(-24 dBFS)와 비교해 이득을 천천히 키우고 빠르게 줄임. 말소리가 아닌 조각은 건드리지 않음(게이트)
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

function makeNoise(kind: string, n: number, seed: number = 0): Float32Array {
  // 잡음 세 가지(실효값 1로 맞춤): white = 선풍기처럼 고른 소리 · car = 낮은 소리에 몰린 웅웅 · hum = 120 · 240 Hz 웅 소리 + 약한 잡음
  const g = gauss(seed);
  const x = new Float64Array(n);
  if (kind === "white") for (let i = 0; i < n; i++) x[i] = g();
  else if (kind === "car") {
    const a = 1 - Math.exp((-2 * Math.PI * 300) / SR); // 300 Hz 아래만 통과시키는 1차 필터 두 번
    let integ = 0;
    let l1 = 0;
    let l2 = 0;
    for (let i = 0; i < n; i++) {
      integ = g() + 0.995 * integ; // 낮은 소리가 크게 쌓이는 웅웅
      l1 += a * (integ - l1);
      l2 += a * (l1 - l2);
      x[i] = l2;
    }
  } else for (let i = 0; i < n; i++) x[i] = 0.6 * Math.sin((2 * Math.PI * 120 * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 240 * i) / SR) + 0.3 * g();
  const rms = Math.sqrt(x.reduce((a, v) => a + v * v, 0) / n);
  return Float32Array.from(x, (v) => v / rms);
}

function activeMask(clean: Float32Array): boolean[] {
  const peak = clean.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  return Array.from(clean, (v) => Math.abs(v) > 0.1 * peak);
}

function meanSq(x: ArrayLike<number>, mask: boolean[]): number {
  let s = 0;
  let c = 0;
  for (let i = 0; i < mask.length; i++)
    if (mask[i]) {
      s += x[i] * x[i];
      c++;
    }
  return s / c;
}

function mixSnr(clean: Float32Array, noise: Float32Array, snrDb: number): Float32Array {
  // 말소리가 있는 곳의 에너지 기준으로 잡음 크기를 맞춰 섞는다: SNR = 10 log10(말소리 에너지 / 잡음 에너지)
  const m = activeMask(clean);
  const g = Math.sqrt(meanSq(clean, m) / (meanSq(noise, m) * 10 ** (snrDb / 10)));
  return clean.map((v, i) => v + g * noise[i]);
}

function measuredSnr(clean: Float32Array, noisy: Float32Array): number {
  const m = activeMask(clean);
  return 10 * Math.log10(meanSq(clean, m) / meanSq(noisy.map((v, i) => v - clean[i]), m));
}

function siSdr(y: ArrayLike<number>, ref: ArrayLike<number>): number {
  // 소리 품질 점수(dB): 깨끗한 소리 성분 대 나머지(잡음 · 왜곡). 크기가 달라도 같은 점수(scale-invariant). 높을수록 좋음
  let yr = 0;
  let rr = 0;
  for (let i = 0; i < ref.length; i++) {
    yr += y[i] * ref[i];
    rr += ref[i] * ref[i];
  }
  const alpha = yr / rr;
  let t = 0;
  let r = 0;
  for (let i = 0; i < ref.length; i++) {
    t += (alpha * ref[i]) ** 2;
    r += (y[i] - alpha * ref[i]) ** 2;
  }
  return 10 * Math.log10(t / (r + 1e-15));
}

const CLEAN = place(synthVoice(4.0, 150, 3).map((v) => 0.5 * v), 5.0, 0.6); // 앞 0.6초는 조용함(잡음만) → 잡음 크기를 배울 구간

const NFFT = 512;
const HOP = 128;

function wienerNs(y: Float32Array, noiseSec: number = 0.4, floor: number = 0.1): [Float32Array, Float64Array[]] {
  // 위너 필터 잡음 억제: 주파수마다 '말소리일 몫'만큼만 남긴다. 이득 G = max(1 - 잡음 에너지 / 칸 에너지, floor)
  const win = Float64Array.from({ length: NFFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / NFFT));
  const nFrames = Math.ceil((y.length + NFFT - HOP) / HOP) + 1;
  const spec: [Float64Array, Float64Array][] = [];
  const power: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const start = k * HOP - (NFFT - HOP);
    const re = new Float64Array(NFFT);
    const im = new Float64Array(NFFT);
    for (let i = 0; i < NFFT; i++) re[i] = start + i >= 0 && start + i < y.length ? y[start + i] * win[i] : 0;
    fft(re, im);
    spec.push([re, im]);
    power.push(re.map((v, i) => v * v + im[i] * im[i]));
  }
  const noiseFrames = power.filter((_, k) => (k * HOP - (NFFT - HOP) + NFFT / 2) / SR < noiseSec);
  const N = new Float64Array(NFFT).map((_, f) => noiseFrames.reduce((a, p) => a + p[f], 0) / noiseFrames.length); // 주파수마다 잡음 에너지 = 앞부분(잡음만) 평균
  const out = new Float64Array(y.length);
  const norm = new Float64Array(y.length);
  const gains: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const G = power[k].map((p, f) => Math.max(1 - N[f] / (p + 1e-12), floor)); // 칸마다 이득, floor보다 작아지지 않게
    gains.push(G.slice(0, NFFT / 2 + 1));
    const re = spec[k][0].map((v, f) => v * G[f]);
    const im = spec[k][1].map((v, f) => v * G[f]);
    fft(re, im, true); // 칸 → 다시 소리
    const start = k * HOP - (NFFT - HOP);
    for (let i = 0; i < NFFT; i++)
      if (start + i >= 0 && start + i < y.length) {
        out[start + i] += re[i] * win[i];
        norm[start + i] += win[i] * win[i];
      }
  }
  return [Float32Array.from(out, (v, i) => v / Math.max(norm[i], 1e-8)), gains];
}

const TARGET_DB = -24; // AGC: 목표 크기
const MAX_GAIN_DB = 24; // 최대 이득
const GATE_DB = -42; // 이보다 작으면 말소리가 아니라고 봄

function agcFrame(f: Float32Array, gDb: number, attack: number = 0.3, release: number = 0.05): [Float32Array, number] {
  // 20 ms 조각 하나 + 지금 이득 → 처리된 조각 + 새 이득
  const lv = levelDb(f);
  if (lv > GATE_DB) {
    // 말소리일 때만 목표를 다시 정함
    const want = Math.max(-MAX_GAIN_DB, Math.min(MAX_GAIN_DB, TARGET_DB - lv)); // 원하는 이득 = 목표 크기 − 지금 크기
    gDb += (want < gDb ? attack : release) * (want - gDb); // 줄일 때는 빠르게, 키울 때는 천천히
  }
  const g = 10 ** (gDb / 20);
  return [f.map((v) => Math.max(-1, Math.min(1, v * g))), gDb];
}

function agc(x: Float32Array): Float32Array {
  const out = new Float32Array(x.length);
  let g = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const [y, ng] = agcFrame(x.subarray(i, i + FRAME), g);
    out.set(y, i);
    g = ng;
  }
  return out;
}

function speechLevel(x: Float32Array, ref: Float32Array, start: number = 0): number {
  // ref에서 말소리가 있는 조각들만 골라 x의 크기 재기 (start초 뒤부터)
  const th = levelDb(ref) - 10;
  let s = 0;
  let c = 0;
  for (let i = Math.floor(start * SR); i + FRAME <= ref.length; i += FRAME)
    if (levelDb(ref, i, i + FRAME) > th) {
      for (let j = i; j < i + FRAME; j++) s += x[j] * x[j];
      c += FRAME;
    }
  return 20 * Math.log10(Math.sqrt(s / c) + 1e-9);
}

const rows: [string, number, number, number][] = [];
const voice = synthVoice(4.0, 150, 3);
for (const [name, gain] of [["작은 목소리 (멀리서)", 0.08], ["보통", 0.25], ["큰 목소리 (바짝 대고)", 0.95]] as [string, number][]) {
  const x = place(voice.map((v) => v * gain), 5.0, 0.6);
  const y = agc(x);
  const before = speechLevel(x, x, 2.0);
  const after = speechLevel(y, x, 2.0); // 2초 뒤(이득이 자리 잡은 뒤) 말소리 크기
  const peak = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  rows.push([name, before, after, peak]);
  console.log(`${name.padEnd(22)} 처리 전 ${before.toFixed(1).padStart(6)} dBFS → 처리 후 ${after.toFixed(1).padStart(6)} dBFS (목표 ${TARGET_DB}) · 최대 진폭 ${peak.toFixed(2)}`);
}
const spread = (i: number): number => Math.max(...rows.map((r) => r[i])) - Math.min(...rows.map((r) => r[i]));
check(rows.every((r) => Math.abs(r[2] - TARGET_DB) < 4), "세 사용자 모두 목표 크기 근처로 모여야 해요.");
check(spread(1) > 20 && spread(2) < 6, "크기 차이가 20 dB 넘게에서 몇 dB로 줄어야 해요.");
check(rows.every((r) => r[3] <= 1.0), "큰 목소리도 -1 ~ 1을 넘지 않게 잘라야 해요(클리핑 방지).");

// 게이트: 말소리가 아니라 잡음뿐인 조각은 이득을 바꾸지 않는다 (안 그러면 쉴 때 잡음이 커짐)
const g = gauss(0);
const noiseFrame = Float32Array.from({ length: FRAME }, () => 0.001 * g()); // 약 -60 dBFS
const [, gAfter] = agcFrame(noiseFrame, 12.0);
console.log(`잡음 조각(${levelDb(noiseFrame).toFixed(0)} dBFS < 게이트 ${GATE_DB}) 뒤 이득: 12.0 → ${gAfter.toFixed(1)} dB`);
check(gAfter === 12.0, "게이트 아래 조각은 이득을 그대로 둬야 해요.");

// attack(줄이기)은 빠르고 release(키우기)는 느리다: 갑자기 큰 소리가 오면 몇 조각 만에 줄고, 작아지면 서서히 오른다
const tone = (amp: number): Float32Array => Float32Array.from({ length: FRAME }, (_, i) => amp * Math.sin((2 * Math.PI * 300 * i) / SR));
let gDown = 0;
let gUp = 0;
let nDown = 0;
let nUp = 0;
while (gDown > -8 && nDown < 200) {
  gDown = agcFrame(tone(0.9), gDown)[1];
  nDown++;
}
while (gUp < 8 && nUp < 400) {
  gUp = agcFrame(tone(0.03), gUp)[1];
  nUp++;
}
console.log(`이득을 8 dB 줄이는 데 ${nDown}조각(${nDown * 20} ms) · 8 dB 키우는 데 ${nUp}조각(${nUp * 20} ms)`);
check(nDown * 3 < nUp, "줄일 때(attack 0.3)가 키울 때(release 0.05)보다 훨씬 빨라야 해요.");

recap.typescript:
// D33 · Part 4 · 전체 체인과 정리 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d33_recap.ts   (합성 목소리로 실행 · 핵심 공식을 한 번씩 확인)
//   AEC · NS · AGC의 핵심 공식을 숫자로 한 번씩 확인 (정리표 순서)
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms = 320 샘플 (D31 · D32와 같은 조각)
const THRESH_DB = -38; // D31 서버의 에너지 VAD 설정 그대로
const HANG_SEC = 0.6;
const TOTAL = 6; // 시험 장면 길이(초)
const DEVICE_DELAY = 0.04; // 재생 버퍼 + 녹음 버퍼 (초)
const COUPLING = 0.15; // 스피커 소리가 마이크까지 오는 크기 (노트북 몸체 · 거리)
const TAPS = 512; // NLMS 기억 길이(512 = 32 ms)
const MU = 0.5; // NLMS 걸음 크기

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(seed: number): () => number {
  // 표준정규분포 난수 (Box-Muller)
  const r = mulberry32(seed);
  return (): number => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
}

function levelDb(x: ArrayLike<number>, from: number = 0, to: number = x.length): number {
  // 소리 크기 (dBFS, 0 = 최대)
  let s = 0;
  for (let i = from; i < to; i++) s += x[i] * x[i];
  return 20 * Math.log10(Math.sqrt(s / Math.max(1, to - from)) + 1e-9);
}

function synthVoice(seconds: number, f0: number, seed: number): Float32Array {
  // 말소리 비슷한 합성 신호(피크 1): 기본음 + 배음 5개 + 음절 모양 세기 + 'ㅅ' 같은 잡음 소리. (대체 경로: Edge TTS 대신)
  const g = gauss(seed);
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  let phase = 0;
  let peak = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR;
    let h = 0;
    for (let k = 1; k <= 5; k++) h += Math.sin(k * phase) / k;
    const v = h * Math.sqrt(Math.max(Math.sin(2 * Math.PI * 2.5 * t), 0)) + 0.6 * g() * Math.max(Math.sin(2 * Math.PI * 4.1 * t + 1), 0) + 0.01 * g();
    y[i] = v;
    peak = Math.max(peak, Math.abs(v));
  }
  return y.map((v) => v / peak);
}

function place(y: ArrayLike<number>, total: number, start: number): Float32Array {
  // y를 total초 길이 장면의 start초 자리에 놓기
  const out = new Float32Array(Math.floor(total * SR));
  const a = Math.floor(start * SR);
  for (let i = 0; i < Math.min(y.length, out.length - a); i++) out[a + i] = y[i];
  return out;
}

function roomIr(seed: number, n: number = 480): Float64Array {
  // 방 울림(RIR) 흉내: 직접 소리 하나(12샘플째) + 벽 반사가 점점 작아지는 꼬리. (대체 경로: pyroomacoustics 대신)
  const g = gauss(seed);
  const h = new Float64Array(n);
  for (let i = 12; i < n; i++) h[i] = g() * Math.exp(-i / (0.01 * SR)) * 0.08;
  h[12] = 1.0;
  return h;
}

function convolveTrunc(x: ArrayLike<number>, h: ArrayLike<number>, len: number = x.length): Float32Array {
  // 합성곱을 앞 len샘플만 (직접 계산. 파이썬은 FFT로 빠르게 하지만 결과는 같다)
  const out = new Float32Array(len);
  for (let i = 0; i < Math.min(x.length, len); i++) {
    const xi = x[i];
    if (xi === 0) continue;
    for (let k = 0; k < h.length && i + k < len; k++) out[i + k] += xi * h[k];
  }
  return out;
}

const RIR_ECHO = roomIr(1);
const RIR_USER = roomIr(2);
const BOT_END = 0.5 + 3.5; // 비서가 말을 마치는 시각
const BARGE_AT = 3.2; // 사용자가 끼어드는 시각
const BARGE_LEN = Math.floor(1.5 * SR);
const FAR = place(synthVoice(3.5, 130, 0).map((v) => 0.8 * v), TOTAL, 0.5); // 스피커로 나간 비서 목소리 (서버가 아는 '기준 신호')
const NEAR = place(convolveTrunc(synthVoice(1.5, 210, 5), RIR_USER, BARGE_LEN).map((v) => 0.4 * v), TOTAL, BARGE_AT); // 사용자 (방 울림 포함)

function speakerToMic(play: Float32Array): Float32Array {
  // 기준 신호 → 마이크에 들어온 에코: 방 울림 합성곱 × 결합 크기 + 장치 지연
  const e = convolveTrunc(play, RIR_ECHO);
  const d = Math.floor(DEVICE_DELAY * SR);
  const out = new Float32Array(play.length);
  for (let i = d; i < out.length; i++) out[i] = e[i - d] * COUPLING;
  return out;
}

const FLOOR = (() => {
  const g = gauss(9);
  return Float32Array.from({ length: FAR.length }, () => 0.0003 * g()); // 마이크 자체 잡음 (-70 dBFS)
})();
const ECHO = speakerToMic(FAR);
const MIC_A = ECHO.map((v, i) => v + FLOOR[i]); // 장면 A: 비서만 말함 (사용자는 조용)
const MIC_B = ECHO.map((v, i) => v + NEAR[i] + FLOOR[i]); // 장면 B: 비서 말 도중 끼어들기 (더블토크)

function vadStarts(x: Float32Array, thresh: number = THRESH_DB, hang: number = HANG_SEC): number[] {
  // D31 Endpointer와 같은 규칙: '말 시작'으로 본 시각들
  const starts: number[] = [];
  let inside = false;
  let quiet = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const db = levelDb(x, i, i + FRAME);
    if (!inside && db > thresh) {
      inside = true;
      quiet = 0;
      starts.push(Math.round((i / SR) * 100) / 100);
    }
    if (inside) {
      quiet = db <= thresh ? quiet + 0.02 : 0;
      if (quiet >= hang) inside = false;
    }
  }
  return starts;
}

function estimateLag(mic: Float32Array, ref: Float32Array, maxLag: number = 2000): number {
  // 상호상관으로 에코 지연(샘플) 찾기: ref를 lag칸 늦췄을 때 마이크와 가장 닮은 칸 (0 ~ maxLag만 훑음)
  let best = 0;
  let bestV = -1;
  for (let lag = 0; lag <= maxLag; lag++) {
    let s = 0;
    for (let n = lag; n < mic.length; n++) s += mic[n] * ref[n - lag];
    if (Math.abs(s) > bestV) {
      bestV = Math.abs(s);
      best = lag;
    }
  }
  return best;
}

function delayed(x: Float32Array, lag: number): Float32Array {
  // x를 lag샘플 늦춤 (길이는 그대로)
  const out = new Float32Array(x.length);
  for (let i = lag; i < x.length; i++) out[i] = x[i - lag];
  return out;
}

function nlmsAec(d: Float32Array, x: Float32Array, taps: number = TAPS, mu: number = MU, eps: number = 1e-2, freeze: boolean[] | null = null): [Float32Array, Float64Array] {
  // NLMS 적응 필터. d: 마이크 · x: 지연을 맞춘 기준 신호 · freeze: true인 샘플에서는 배우지 않음(더블토크)
  // eps는 기준 신호가 거의 없을 때 0으로 나누다 폭주하지 않게 하는 작은 바닥값
  const w = new Float64Array(taps);
  const e = new Float32Array(d.length);
  for (let n = 0; n < d.length; n++) {
    let y = 0;
    let en = 0;
    for (let j = 0; j < taps; j++) {
      const xv = n - j >= 0 ? x[n - j] : 0; // 최근 taps개 기준 신호 (가장 최근이 맨 앞)
      y += w[j] * xv;
      en += xv * xv;
    }
    e[n] = d[n] - y; // 남은 소리 = 마이크 − 에코 예측
    if (!freeze || !freeze[n]) {
      const k = (mu * e[n]) / (en + eps); // 기준 신호 에너지로 나눠 고치기
      for (let j = 0; j < taps; j++) if (n - j >= 0) w[j] += k * x[n - j];
    }
  }
  return [e, w];
}

function erleDb(d: Float32Array, e: Float32Array): number {
  // 에코를 몇 dB 줄였나 (ERLE)
  let a = 0;
  let b = 0;
  for (let i = 0; i < d.length; i++) {
    a += d[i] * d[i];
    b += e[i] * e[i];
  }
  return 10 * Math.log10(a / d.length / (b / d.length + 1e-15));
}

function geigel(d: Float32Array, x: Float32Array, look: number = TAPS, T: number = 0.5, hold: number = 0.15): boolean[] {
  // true = 사용자도 말하는 중 → 배우지 않음. 마이크가 '최근 기준 신호 최댓값의 T배'를 넘으면 더블토크
  const holdN = Math.floor(hold * SR);
  const out: boolean[] = new Array(d.length).fill(false);
  let lastTalk = -1e9;
  for (let n = 0; n < d.length; n++) {
    let xm = 0;
    for (let j = Math.max(0, n - look); j < n; j++) xm = Math.max(xm, Math.abs(x[j]));
    if (Math.abs(d[n]) > T * xm && xm > 1e-3) lastTalk = n;
    out[n] = n - lastTalk < holdN;
  }
  return out;
}

function slice(x: Float32Array, a: number, b: number): Float32Array {
  return x.subarray(Math.floor(a * SR), Math.floor(b * SR));
}

function makeNoise(kind: string, n: number, seed: number = 0): Float32Array {
  // 잡음 세 가지(실효값 1로 맞춤): white = 선풍기처럼 고른 소리 · car = 낮은 소리에 몰린 웅웅 · hum = 120 · 240 Hz 웅 소리 + 약한 잡음
  const g = gauss(seed);
  const x = new Float64Array(n);
  if (kind === "white") for (let i = 0; i < n; i++) x[i] = g();
  else if (kind === "car") {
    const a = 1 - Math.exp((-2 * Math.PI * 300) / SR); // 300 Hz 아래만 통과시키는 1차 필터 두 번
    let integ = 0;
    let l1 = 0;
    let l2 = 0;
    for (let i = 0; i < n; i++) {
      integ = g() + 0.995 * integ; // 낮은 소리가 크게 쌓이는 웅웅
      l1 += a * (integ - l1);
      l2 += a * (l1 - l2);
      x[i] = l2;
    }
  } else for (let i = 0; i < n; i++) x[i] = 0.6 * Math.sin((2 * Math.PI * 120 * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 240 * i) / SR) + 0.3 * g();
  const rms = Math.sqrt(x.reduce((a, v) => a + v * v, 0) / n);
  return Float32Array.from(x, (v) => v / rms);
}

function activeMask(clean: Float32Array): boolean[] {
  const peak = clean.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  return Array.from(clean, (v) => Math.abs(v) > 0.1 * peak);
}

function meanSq(x: ArrayLike<number>, mask: boolean[]): number {
  let s = 0;
  let c = 0;
  for (let i = 0; i < mask.length; i++)
    if (mask[i]) {
      s += x[i] * x[i];
      c++;
    }
  return s / c;
}

function mixSnr(clean: Float32Array, noise: Float32Array, snrDb: number): Float32Array {
  // 말소리가 있는 곳의 에너지 기준으로 잡음 크기를 맞춰 섞는다: SNR = 10 log10(말소리 에너지 / 잡음 에너지)
  const m = activeMask(clean);
  const g = Math.sqrt(meanSq(clean, m) / (meanSq(noise, m) * 10 ** (snrDb / 10)));
  return clean.map((v, i) => v + g * noise[i]);
}

function measuredSnr(clean: Float32Array, noisy: Float32Array): number {
  const m = activeMask(clean);
  return 10 * Math.log10(meanSq(clean, m) / meanSq(noisy.map((v, i) => v - clean[i]), m));
}

function siSdr(y: ArrayLike<number>, ref: ArrayLike<number>): number {
  // 소리 품질 점수(dB): 깨끗한 소리 성분 대 나머지(잡음 · 왜곡). 크기가 달라도 같은 점수(scale-invariant). 높을수록 좋음
  let yr = 0;
  let rr = 0;
  for (let i = 0; i < ref.length; i++) {
    yr += y[i] * ref[i];
    rr += ref[i] * ref[i];
  }
  const alpha = yr / rr;
  let t = 0;
  let r = 0;
  for (let i = 0; i < ref.length; i++) {
    t += (alpha * ref[i]) ** 2;
    r += (y[i] - alpha * ref[i]) ** 2;
  }
  return 10 * Math.log10(t / (r + 1e-15));
}

const CLEAN = place(synthVoice(4.0, 150, 3).map((v) => 0.5 * v), 5.0, 0.6); // 앞 0.6초는 조용함(잡음만) → 잡음 크기를 배울 구간

const NFFT = 512;
const HOP = 128;

function wienerNs(y: Float32Array, noiseSec: number = 0.4, floor: number = 0.1): [Float32Array, Float64Array[]] {
  // 위너 필터 잡음 억제: 주파수마다 '말소리일 몫'만큼만 남긴다. 이득 G = max(1 - 잡음 에너지 / 칸 에너지, floor)
  const win = Float64Array.from({ length: NFFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / NFFT));
  const nFrames = Math.ceil((y.length + NFFT - HOP) / HOP) + 1;
  const spec: [Float64Array, Float64Array][] = [];
  const power: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const start = k * HOP - (NFFT - HOP);
    const re = new Float64Array(NFFT);
    const im = new Float64Array(NFFT);
    for (let i = 0; i < NFFT; i++) re[i] = start + i >= 0 && start + i < y.length ? y[start + i] * win[i] : 0;
    fft(re, im);
    spec.push([re, im]);
    power.push(re.map((v, i) => v * v + im[i] * im[i]));
  }
  const noiseFrames = power.filter((_, k) => (k * HOP - (NFFT - HOP) + NFFT / 2) / SR < noiseSec);
  const N = new Float64Array(NFFT).map((_, f) => noiseFrames.reduce((a, p) => a + p[f], 0) / noiseFrames.length); // 주파수마다 잡음 에너지 = 앞부분(잡음만) 평균
  const out = new Float64Array(y.length);
  const norm = new Float64Array(y.length);
  const gains: Float64Array[] = [];
  for (let k = 0; k < nFrames; k++) {
    const G = power[k].map((p, f) => Math.max(1 - N[f] / (p + 1e-12), floor)); // 칸마다 이득, floor보다 작아지지 않게
    gains.push(G.slice(0, NFFT / 2 + 1));
    const re = spec[k][0].map((v, f) => v * G[f]);
    const im = spec[k][1].map((v, f) => v * G[f]);
    fft(re, im, true); // 칸 → 다시 소리
    const start = k * HOP - (NFFT - HOP);
    for (let i = 0; i < NFFT; i++)
      if (start + i >= 0 && start + i < y.length) {
        out[start + i] += re[i] * win[i];
        norm[start + i] += win[i] * win[i];
      }
  }
  return [Float32Array.from(out, (v, i) => v / Math.max(norm[i], 1e-8)), gains];
}

const TARGET_DB = -24; // AGC: 목표 크기
const MAX_GAIN_DB = 24; // 최대 이득
const GATE_DB = -42; // 이보다 작으면 말소리가 아니라고 봄

function agcFrame(f: Float32Array, gDb: number, attack: number = 0.3, release: number = 0.05): [Float32Array, number] {
  // 20 ms 조각 하나 + 지금 이득 → 처리된 조각 + 새 이득
  const lv = levelDb(f);
  if (lv > GATE_DB) {
    // 말소리일 때만 목표를 다시 정함
    const want = Math.max(-MAX_GAIN_DB, Math.min(MAX_GAIN_DB, TARGET_DB - lv)); // 원하는 이득 = 목표 크기 − 지금 크기
    gDb += (want < gDb ? attack : release) * (want - gDb); // 줄일 때는 빠르게, 키울 때는 천천히
  }
  const g = 10 ** (gDb / 20);
  return [f.map((v) => Math.max(-1, Math.min(1, v * g))), gDb];
}

function agc(x: Float32Array): Float32Array {
  const out = new Float32Array(x.length);
  let g = 0;
  for (let i = 0; i + FRAME <= x.length; i += FRAME) {
    const [y, ng] = agcFrame(x.subarray(i, i + FRAME), g);
    out.set(y, i);
    g = ng;
  }
  return out;
}

function speechLevel(x: Float32Array, ref: Float32Array, start: number = 0): number {
  // ref에서 말소리가 있는 조각들만 골라 x의 크기 재기 (start초 뒤부터)
  const th = levelDb(ref) - 10;
  let s = 0;
  let c = 0;
  for (let i = Math.floor(start * SR); i + FRAME <= ref.length; i += FRAME)
    if (levelDb(ref, i, i + FRAME) > th) {
      for (let j = i; j < i + FRAME; j++) s += x[j] * x[j];
      c += FRAME;
    }
  return 20 * Math.log10(Math.sqrt(s / c) + 1e-9);
}

// 1) 20 ms 조각 = 320샘플, 에코 지연 = 장치 지연 + 직접 경로
const absH = Array.from(RIR_ECHO, Math.abs);
check(FRAME === 320 && Math.floor(DEVICE_DELAY * SR) + absH.indexOf(Math.max(...absH)) === 652, "20 ms = 320샘플, 지연 40 ms + 직접 경로 12샘플 = 652샘플이에요.");

// 2) 상호상관: 기준 신호를 d샘플 늦춘 마이크라면 정점이 정확히 d
const ref = synthVoice(1.0, 140, 1);
check(estimateLag(delayed(ref, 200), ref) === 200, "상호상관의 정점 위치가 지연이에요.");

// 3) ERLE = 10 log10(처리 전 에너지 / 처리 후 에너지): 진폭을 10분의 1로 줄이면 20 dB
const x = synthVoice(1.0, 140, 2);
check(Math.abs(erleDb(x, x.map((v) => 0.1 * v)) - 20) < 1e-3, "진폭 1/10 = 에너지 1/100 = 20 dB예요.");

// 4) Geigel: 마이크가 기준 신호 최댓값의 T배를 넘으면 사용자도 말하는 중
const far = new Float32Array(2048).fill(0.8);
const quiet = new Float32Array(2048).fill(0.1);
const loud = new Float32Array(2048).fill(0.6);
check(!geigel(quiet, far)[1000] && geigel(loud, far)[1000], "에코 크기(0.1)는 통과, 0.8의 절반(0.4)을 넘는 0.6은 더블토크예요.");

// 5) NLMS 한 걸음: 기준 신호 에너지로 나누므로 기준 신호가 커져도 걸음 크기는 같다
const xb = [1.0, 0.5, 0.25, 0.125];
const stepOf = (s: number): number => {
  const v = xb.map((a) => a * s);
  const energy = v.reduce((a, b) => a + b * b, 0);
  return v.reduce((a, b) => a + ((MU * 1.0 * b) / (energy + 1e-2)) * b, 0); // 한 걸음 뒤 예측이 얼마나 바뀌나
};
check(Math.abs(stepOf(1) - stepOf(10)) < 0.01, "NLMS는 기준 신호 크기에 상관없이 같은 비율로 배워요.");

// 6) SNR 맞추기
const noisy = mixSnr(CLEAN, makeNoise("white", CLEAN.length), 10);
check(Math.abs(measuredSnr(CLEAN, noisy) - 10) < 0.05, "섞은 뒤 잰 SNR이 목표와 같아야 해요.");

// 7) 위너 이득: 칸 에너지가 잡음 에너지와 같으면 1 - 1 = 0 → floor까지 줄어든다. 칸이 잡음의 100배면 0.99
const G = (P: number, N: number, floor: number = 0.1): number => Math.max(1 - N / P, floor);
check(G(1, 1) === 0.1 && Math.abs(G(100, 1) - 0.99) < 1e-9, "이득 = max(1 - 잡음 / 칸 에너지, floor)예요.");

// 8) AGC 원하는 이득 = 목표 - 지금 크기 (최대 이득 ±24 dB로 제한)
const want = (lv: number): number => Math.max(-MAX_GAIN_DB, Math.min(MAX_GAIN_DB, TARGET_DB - lv));
check(want(-44) === 20 && want(-10) === -14 && want(-80) === MAX_GAIN_DB, "목표 -24 dBFS: -44면 +20 dB, -10이면 -14 dB, 너무 작으면 +24 dB에서 멈춰요.");
